test('pause and resume', async () => {
  const h = await createHost();
  refused(await h.pause('x'));
  refused(await h.resume('x'));
  await h.start('r');
  refused(await h.resume('r'));
  await h.taskStarted('r', 0);
  assert.deepEqual(await h.pause('r'), ok);
  refused(await h.pause('r'));
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'running', task1: 'queued', task2: 'queued', paused: true });
  refused(await h.taskStarted('r', 1));
  assert.deepEqual(await h.taskEvicted('r', 0), ok);
  assert.deepEqual(await h.taskRequeued('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: true });
  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await h.resume('r'), ok);
  assert.equal((await h.run('r'))!.paused, false);
  assert.deepEqual(await h.taskStarted('r', 1), ok);
  await h.pause('r');
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: true });
  refused(await h.resume('r'));
});

