import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
const refused = (r: any) => assert.equal(r.ok, false, JSON.stringify(r));

test('start, unknown run, duplicate', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  refused(await h.taskStarted('a', 0));
  refused(await h.cancel('a'));
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: false });
  refused(await h.start('a'));
});

test('bad task numbers and moves are refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const n of [3, -1, 1.5]) refused(await h.taskStarted('r', n));
  refused(await h.taskCompleted('r', 0));
  refused(await h.taskRequeued('r', 0));
  refused(await h.taskEvicted('r', 0));
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: false });
});

test('completion, eviction, requeue', async () => {
  const h = await createHost();
  await h.start('r');
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskEvicted('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskRequeued('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'queued');
  for (const i of [0, 1, 2]) assert.deepEqual(await h.taskStarted('r', i), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  for (const i of [0, 1, 2]) assert.deepEqual(await h.taskEvicted('r', i), ok);
  assert.equal((await h.run('r'))!.status, 'evicted');
  for (const i of [0, 1, 2]) { await h.taskRequeued('r', i); await h.taskStarted('r', i); }
  await h.taskCompleted('r', 0); await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskCompleted('r', 2), ok);
  assert.equal((await h.run('r'))!.status, 'completed');
  refused(await h.cancel('r'));
  refused(await h.start('r'));
});

test('a failed run accepts commands, and a failed task can be retried', async () => {
  const h = await createHost();
  await h.start('r');
  refused(await h.taskRetried('r', 0));
  await h.taskStarted('r', 1);
  assert.deepEqual(await h.taskFailed('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued', paused: false });
  refused(await h.start('r'));
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'failed');
  refused(await h.taskRetried('r', 0));
  refused(await h.taskRetried('r', 3));
  assert.deepEqual(await h.taskRetried('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'running', task1: 'queued', task2: 'queued', paused: false });
  for (const i of [1, 2]) await h.taskStarted('r', i);
  for (const i of [0, 1, 2]) await h.taskFailed('r', i);
  assert.equal((await h.run('r'))!.status, 'failed');
  for (const i of [0, 1, 2]) assert.deepEqual(await h.taskRetried('r', i), ok);
  assert.equal((await h.run('r'))!.status, 'queued');
  for (const i of [0, 1, 2]) { await h.taskStarted('r', i); await h.taskCompleted('r', i); }
  assert.equal((await h.run('r'))!.status, 'completed');
  refused(await h.taskRetried('r', 0));
});

test('cancel on a failed run leaves it failed, then retry and cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0); await h.taskFailed('r', 0);
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled', paused: false });
  refused(await h.cancel('r'));
  assert.deepEqual(await h.taskRetried('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: false });
  refused(await h.taskRetried('r', 0));
});

test('cancel one task', async () => {
  const h = await createHost();
  refused(await h.cancelTask('x', 0));
  await h.start('r');
  refused(await h.cancelTask('r', 3));
  assert.deepEqual(await h.cancelTask('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued', paused: false });
  refused(await h.cancelTask('r', 0));
  await h.taskStarted('r', 1); await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), ok);
  await h.taskStarted('r', 2); await h.taskFailed('r', 2);
  assert.equal((await h.run('r'))!.status, 'failed');
  refused(await h.cancelTask('r', 2));
  await h.taskRetried('r', 2);
  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: false });
  refused(await h.taskRetried('r', 2));

  await h.start('s');
  await h.cancelTask('s', 0);
  for (const i of [1, 2]) { await h.taskStarted('s', i); await h.taskCompleted('s', i); }
  assert.deepEqual(await h.run('s'), { status: 'cancelled', task0: 'cancelled', task1: 'completed', task2: 'completed', paused: false });
  refused(await h.cancel('s'));
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0); await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1); await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled', paused: false });
  refused(await h.cancel('r'));
  await h.start('s');
  assert.deepEqual(await h.cancel('s'), ok);
  assert.deepEqual(await h.run('s'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: false });
});
